--[=[
	@class WuKongContainerLoader
	@client
	此模块需要单独引用, 用来更改客户端的 WuKongInstance 对象.
]=]

local wukong = require(game.ReplicatedStorage.WuKong)

local WuKongContainerLoader = {}

--- 重设悟空实例容器
function WuKongContainerLoader.SetContainer(container: any)
	-- 客户端设置root, 不需要启动
	wukong.__facade:SetRoot(container, true)
end

--- 获取当前悟空实例对应的容器
function WuKongContainerLoader.GetCurrentContainer()
	return wukong.__facade:GetContainer()
end

--- 序列化悟空容器, 返回表对象(containerStaff), 可以进行网络传输
function WuKongContainerLoader.SerializeWuKongContainer(container: any)
	return wukong.__facade:SerializeWuKongContainer(container)
end

--- 反序列化悟空容器, 返回 Container
function WuKongContainerLoader.DeserializeWuKongContainer(userId: number, containerData: any)
	return wukong.__facade:DeserializeWuKongContainer(userId, containerData)
end

return WuKongContainerLoader
